/* Reference the 'TAQ Programs' folder. Run each of the code sections inside ('Trading Activity Program', 'Open Close Price Program', 'Bid Ask Spread Program', and 'Append Daily Files') */
/* Import the ensuing datasets here: "master", "tradesandvolume", "WRDS_TAQ_Query", "effectivespreads", and "openandclose" */



/*Download daily volume data from CRSP beginning 1/1/2016. Name the file CRSP_Shares */

/*Download annual asset data from compustat. Name the file "annual_assets*/

/*To get the CUSIPS to match the PCAOB's database on. */
/* Use the annual assets file to create a CIK to CUSIP match */

proc sql;
	create table CIK_to_CUSIP as
	select cik, cusip, count(cusip)
	from annual_assets
	group by cik, cusip;
quit;

data cik_to_cusip;
set cik_to_cusip;
	if cik ^= .;
run;

/* Reference the R file entitled 'Merge Outside Part with Inspection Findings' */
/* Import the ensuing file and name it PCAOB_Inspections */


/*Importing the PCAOB Inspection Findings */
data PCAOB_Inspections;
set PCAOB_Inspections;
	dum_deficiency = 0;
	dum_deficiency_gaap = 0;
	dum_deficiency_majority = 0;
	dum_deficiency_foreign = 0;
	percent_deficiency = Number_of_Deficient_Audits___Au / Number_of_Audits_Inspected___Au;
	if audit_deficiencies = "Yes" then dum_deficiency = 1;
	if GAAP_Departure_Deficiencies ^= "NA" then dum_deficiency_gaap = 1;
	if percent_deficiency >= .5 then dum_deficiency_majority = 1;
	if i_country ^= "United States" and audit_deficiencies = "Yes" then dum_deficiency_foreign = 1; 
run;

/*Note: this is where other information from the PCOAB data (like range of participation) can be merged in*/
proc sql;
	Create table VolumeFormAP as
	select a.*, b.CIK, b.Fiscal_Period_End_Date, b.Filing_Date, b.Edited_Date, b.big4, b.audit_report_date, b.is_audit_not_divided, b.Form_Filing_ID, b.engagement_partner_ID, b.dum_badcountry,  
	b.named_count, b.number_of_participants, b.totalmid_outside, b.dum_male, b.partner_switch, b.dum_deficiency, b.dum_deficiency_gaap, b.dum_deficiency_majority, b.dum_deficiency_foreign,
	b.ind, b.SIC, b.busy_partner, b.multiyear_disclosure, b.third_disclosure 
	from VolumeMaster_CRSP as a
	inner join identifiers2 as b
	on a.cusip = b.cusip;

proc sql; 
create Table Identifiers as
	Select A.*, B.*
	from CIK_to_CUSIP as A
	Inner Join PCAOB_filing_busy as B 
	on a.CIK=b.padded_CIK;
quit;

/* The dataset volumerestatements2 can be exported to Stata and used for the primary analysis */
/* Upon importing that dataset to Stata, use the following code to adjust for outliers and scale for presentation */

/*Trimming the variables to adjust for outliers */
winsor2 percent_resid, trim
winsor2 effectivespread_percent_sw, trim
winsor2 equal_adjusted_daily, trim
gen abs_equal_adjusted_tr = abs(equal_adjusted_daily_tr)

/* Scaling variables to assist in the presentation */
gen effectivespread_percent_scaled = effectivespread_percent_sw_tr * 1000
gen abs_equal_adjusted_scaled = abs_equal_adjusted_tr * 100

/* Merging in the filing date information to the outside participants file */
proc sql;
	create table outside_participants2
	as select a.filing_date, b.*
	from pcaob_filing as a
	inner join outside_participants as b
	on a.form_filing_id = b.form_filing_id;

/*Manipulating the CRSP Shares Data File to calculate actual shares outstanding and percent of shares traded */
data CRSP_shares;
set CRSP_Shares;
	scaled_CRSP_shares = shrout * 1000; 
	percent_traded_CRSP = (vol / scaled_CRSP_shares)*100;
run;


/*Merging the CRSP data with the TAQ data. */
proc sql;
	Create table VolumeMaster_CRSP as 
	select a.*, b.shrout, b.vol, b.scaled_CRSP_shares, b.percent_traded_CRSP
	from VolumeMaster_count as a
	left join CRSP_Shares as b
	on a.CUSIP8 = b.CUSIP 
	and a.date = b.date;
quit;

/* Reference the 'EDGAR Programs' folder. Run the R file entitled 'EDGAR Filing Script'.
/* Import the ensuing dataset and name it "SEC_Filings" */

/* Working with the SEC files */
/*create padded CIKs in master file */;
data SEC_filings;
length mergecik $ 10;
set SEC_filings;
	mergecik = cik;
	padded_CIK = translate(right(mergecik),'0',' ');
	rename form_type = formtype;
	datefiled = input(date_filed, yymmdd10.);
	format datefiled yymmdd10.;
run;

/* Download earning announcement dates from Compustat. 
Name the file RDQ_Date */


/* Creating a -1 to +5 day window for earnings announcements */
proc sql;
	create table VolumeFormAP4 as 
	select a.*, b.RDQ
	from MergeTable4 as a
	left join RDQ_Date as b
	on a.CUSIP = b.CUSIP
	and a.date = b.rdq;
quit;

/*Bringing over the annual assets */
data annual_assets;
set annual_assets;
	year_end = year(datadate);
run;

/*Creating a list of each Form AP in the sample */
data ap_list;
set MergeTable6;
	if event_window = 0;
	fiscal_year_end = year(Fiscal_Period_End_Date);
run;

proc sql;
	create table ap_list_assets 
	as select a.*, b.at
	from ap_list as a
	inner join annual_assets as b
	on a.cik = b.cik
	and a.fiscal_year_end = b.year_end;
quit;

/*Download SIC codes from COMPUSTATs fundamentals annual and name the file SIC_Codes */ 

/* Linking a SIC code to the PCAOB data. */
proc sort data = SIC_codes;
	by CUSIP descending fyear ;
run;

data SIC_codes;
set SIC_codes;
	repeat = 0;
	if cusip = lag(CUSIP) then repeat = 1;
run;

data SIC_Codes;
set SIC_Codes;
	if repeat ^= 1;
run;

/*Merging the SIC codes into the Form AP database */
proc sql;
	create table identifiers2 as
	select a.*, b.sic
	from identifiers as a
	inner join sic_codes as b
	on a.CIK = b.CIK;
quit;

/* Download CRSP data beginning from 1/1/2008. Name the dataset Historical_Volume */
data Historical_Volume;
set Historical_Volume;
	scaled_CRSP_shares = shrout * 1000; 
	percent_traded_CRSP = (vol / scaled_CRSP_shares)*100;
run;


data Historical_volume1;
set Historical_volume;
	if date < '01jan2017'd;
run;

/* Renaming TAQ variables */
data Historical_Volume_TAQ2;
set VolumeMaster2;
	if date >= '01jan2017'd;
	if date < '01jan2020'd;
	rename date = dateTAQ;
	rename CUSIP = CUSIPTAQ;
	if sym_suffix = " ";
run;

/* Stacking the CRSP and TAQ data */
data Historical_Volume_A;
set historical_volume1 historical_volume_TAQ2;
run;

/*Creating a variable that contains the TAQ and CRSP information */
data Historical_Volume_A;
set Historical_Volume_A;
	if dateTAQ = "." then date_all = date;
	if date =  "." then date_all = dateTAQ;
	if totalvolume = "." then vol_all = vol;
	if vol = "." then vol_all = totalvolume;
	if scaled_CRSP_shares = "." then scaled_outstanding = scaled_shares;
	if scaled_shares = "." then scaled_outstanding = scaled_CRSP_shares;
	if ticker = "." then firm_ticker = sym_root;
	if sym_root = "." then firm_ticker = ticker;
	firm_ticker2 = catx("", ticker, sym_root);
	if numtrd = "." then trades_all = totaltrades;
	if totaltrades = "." then trades_all = numtrd;
run;

/* Download fiscal quarter data from Compustat. Name the data set Fiscal_Quarters */
data Fiscal_quarters;
set Fiscal_quarters;
	year_index = fyearq * 4 + fqtr;
run;


proc sql;
	create table Fiscal_quarters2 as 
	select a.*, b.datadate as prior1
	from Fiscal_quarters as a
	inner join fiscal_quarters as b 
	on a.CIK = b.CIK 
	and a.year_index = b.year_index + 1;
quit;

proc sql;
	create table Fiscal_quarters3 as 
	select a.*, b.datadate as prior2
	from Fiscal_quarters2 as a
	inner join fiscal_quarters as b 
	on a.CIK = b.CIK 
	and a.year_index = b.year_index + 2;
quit;

/*Merging the SIC codes into the Form AP database */
proc sql;
	create table identifiers2 as
	select a.*, b.sic
	from identifiers as a
	inner join sic_codes as b
	on a.CIK = b.CIK;
quit;

/* Reference the Stata file entitled 'AA to PCAOB Restatement Link' */
/* Import the ensuing dataset and name it Restatements */


/* Getting rid of any duplicate observations */
proc sort data = Restatements;
	by cikcode;
run;

data Restatements;
set Restatements;
	duplicate = 0;
	if formfilingid = lag(formfilingid) then duplicate = 1;
run;
